mod common;

use common::Harness;
use serde_json::json;

fn send(h: &mut Harness, queue: &str, body: &str) -> serde_json::Value {
    h.run(json!({"Command": "SendMessage", "QueueName": queue, "Body": body}))
}

#[test]
fn default_is_1024_and_always_reported() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    let r = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}));
    assert_eq!(r["Attributes"]["MaxMessageBytes"], 1024);
}

#[test]
fn attribute_range_is_1_to_1024() {
    let mut h = Harness::new();
    for bad in [json!(0), json!(1025), json!("5"), json!(5.5)] {
        assert_eq!(
            h.err(json!({"Command": "CreateQueue", "QueueName": "q",
                         "Attributes": {"MaxMessageBytes": bad}})),
            "InvalidParameterValue"
        );
    }
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 1}}));
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q",
                "Attributes": {"MaxMessageBytes": 1024}}));
    assert_eq!(
        h.err(json!({"Command": "SetQueueAttributes", "QueueName": "q",
                     "Attributes": {"MaxMessageBytes": 0}})),
        "InvalidParameterValue"
    );
}

#[test]
fn takes_part_in_create_idempotency() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 10}}));
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 10}}));
    assert_eq!(
        h.err(json!({"Command": "CreateQueue", "QueueName": "q"})),
        "QueueAlreadyExists"
    );
}

#[test]
fn limit_counts_utf8_bytes() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 4}}));
    assert_eq!(send(&mut h, "q", "abcd")["ok"], true);
    assert_eq!(send(&mut h, "q", "abcde")["error"]["code"], "InvalidParameterValue");
    // Two characters, four bytes.
    assert_eq!(send(&mut h, "q", "éé")["ok"], true);
    // Two characters, six bytes.
    assert_eq!(send(&mut h, "q", "€€")["error"]["code"], "InvalidParameterValue");
}

#[test]
fn rule_precedes_the_other_send_rules() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q", "Attributes": {"MaxMessageBytes": 1}}));
    // Would be UnsupportedOperation without the size rule.
    assert_eq!(
        h.err(json!({"Command": "SendMessage", "QueueName": "q", "Body": "ab", "GroupId": "g"})),
        "InvalidParameterValue"
    );
}

#[test]
fn lowering_the_limit_keeps_existing_messages() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q"}));
    send(&mut h, "q", "long body");
    h.ok(json!({"Command": "SetQueueAttributes", "QueueName": "q",
                "Attributes": {"MaxMessageBytes": 1}}));
    let r = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    assert_eq!(r["Messages"][0]["Body"], "long body");
}

#[test]
fn dead_letter_moves_ignore_the_limit() {
    let mut h = Harness::new();
    h.ok(json!({"Command": "CreateQueue", "QueueName": "dlq", "Attributes": {"MaxMessageBytes": 1}}));
    h.ok(json!({"Command": "CreateQueue", "QueueName": "q",
                "Attributes": {"DeadLetterQueue": "dlq", "MaxReceiveCount": 1, "VisibilityTimeout": 0}}));
    send(&mut h, "q", "long body");
    h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    // Second receive moves the message to the dead-letter queue.
    h.ok(json!({"Command": "ReceiveMessage", "QueueName": "q"}));
    let r = h.ok(json!({"Command": "ReceiveMessage", "QueueName": "dlq"}));
    assert_eq!(r["Messages"][0]["Body"], "long body");
}
